package EmployeeManagementSystem.controller;
import EmployeeManagementSystem.entity.*; import EmployeeManagementSystem.security.jwt.JwtUtil; import EmployeeManagementSystem.repository.EmployeeRepository; import EmployeeManagementSystem.service.GrievanceService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/grievances") public class GrievanceController{
 private final GrievanceService s; private final JwtUtil jwt; private final EmployeeRepository employees; public GrievanceController(GrievanceService s,JwtUtil j,EmployeeRepository e){this.s=s;jwt=j;employees=e;}
 private String token(String a){if(a==null||!a.startsWith("Bearer "))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Authentication required.");return a.substring(7);} private String user(String a){return jwt.extractUsername(token(a));} private String role(String a){String r=jwt.extractRole(token(a));return r==null?"":r.replace("ROLE_","").toUpperCase();} private boolean mgmt(String r){return Set.of("ADMIN","HR").contains(r);} private RuntimeException bad(Exception e){return new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}
 @GetMapping("/my") public List<GrievanceCase> my(@RequestHeader("Authorization")String a){return s.my(user(a));}
 @GetMapping("/all") public List<GrievanceCase> all(@RequestHeader("Authorization")String a){if(!mgmt(role(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"HR management access required.");return s.all();}
 @GetMapping("/{id}") public GrievanceCase get(@PathVariable Long id,@RequestHeader("Authorization")String a){try{GrievanceCase g=s.get(id);String u=user(a);if(!u.equals(g.getUserId())&&!mgmt(role(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Access denied.");return g;}catch(NoSuchElementException e){throw new ResponseStatusException(HttpStatus.NOT_FOUND,e.getMessage());}}
 @PostMapping public GrievanceCase create(@RequestHeader("Authorization")String a,@RequestBody GrievanceCase x){String u=user(a);String n=employees.findByRegisterEmployee_UserId(u).map(Employee::getFullName).orElse(u);try{return s.create(x,u,n);}catch(Exception e){throw bad(e);}}
 @PutMapping("/{id}") public GrievanceCase update(@PathVariable Long id,@RequestHeader("Authorization")String a,@RequestBody GrievanceCase x){try{return s.update(id,x,user(a),mgmt(role(a)));}catch(Exception e){throw bad(e);}}
 @PatchMapping("/{id}/review") public GrievanceCase review(@PathVariable Long id,@RequestHeader("Authorization")String a,@RequestBody Map<String,String>b){try{return s.review(id,b.get("status"),b.get("resolution"),b.get("assignedTo"),b.getOrDefault("assignedTeam","HR"),user(a),mgmt(role(a)));}catch(Exception e){throw bad(e);}}
 @GetMapping("/{id}/comments") public List<GrievanceComment> comments(@PathVariable Long id,@RequestHeader("Authorization")String a){try{GrievanceCase g=s.get(id);if(!user(a).equals(g.getUserId())&&!mgmt(role(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Access denied.");return s.comments(id);}catch(NoSuchElementException e){throw new ResponseStatusException(HttpStatus.NOT_FOUND,e.getMessage());}}
 @PostMapping("/{id}/comments") public GrievanceComment comment(@PathVariable Long id,@RequestHeader("Authorization")String a,@RequestBody Map<String,String>b){String u=user(a);String n=employees.findByRegisterEmployee_UserId(u).map(Employee::getFullName).orElse(u);try{return s.addComment(id,u,n,b.get("comment"),mgmt(role(a)));}catch(Exception e){throw bad(e);}}
}
